namespace sv_9f016bfe723147cbbb5aaba852a8f7f3.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Interactive Server mode, Scoped lifetime = one per circuit (user session).
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0078d4";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon()
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️ Light",
        Services.ThemeMode.Dark => "🌙 Dark",
        Services.ThemeMode.System => "💻 System",
        _ => "💻 System"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <div class="setting-group">
        <label>Theme</label>
        <select @bind="SelectedTheme">
            <option value="@Services.ThemeMode.Light">Light</option>
            <option value="@Services.ThemeMode.Dark">Dark</option>
            <option value="@Services.ThemeMode.System">System</option>
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="AccentColor" />
        <span style="color: @AccentColor;">Sample text</span>
    </div>
</div>

<p><em>Changes apply immediately across all components.</em></p>

@code {
    private Services.ThemeMode SelectedTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    private string AccentColor
    {
        get => ThemeService.AccentColor;
        set => ThemeService.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

